(()=>{const go=e=>{const el=e.target?.closest?.('button,a,[role="button"]');if(!el||!/adquirir\s+un\s+plan/i.test(el.textContent||''))return;e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();location.href='/assets/planes.html#dj-plans'};['pointerdown','mousedown','touchstart','click'].forEach(n=>document.addEventListener(n,go,true));const OLD_FOLDER="https://drive.google.com/drive/folders/1UTIQESYvJcNdKXNsDdDs0dRCrDzs5JvF",NEW_FOLDER="https://drive.google.com/drive/folders/1iwuKlMfb8JSLV86ZlbPNQg1ri2Q0CeNl",API="https://rcmusic-eventos.onrender.com/api";const patchLabel=()=>document.querySelectorAll("button").forEach(button=>{const w=document.createTreeWalker(button,NodeFilter.SHOW_TEXT),nodes=[];let n;while(n=w.nextNode())nodes.push(n);nodes.forEach(t=>{if(t.nodeValue.includes("Backup actualizado en Drive"))t.nodeValue=t.nodeValue.replace("Backup actualizado en Drive","Actualización y Utilidades Dj.")})});const originalOpen=window.open;window.open=(url,...args)=>originalOpen.call(window,url===OLD_FOLDER?NEW_FOLDER:url,...args);const headers=()=>{const s=localStorage.getItem("rc_drive_session")||sessionStorage.getItem("rc_drive_session")||"";return {"Content-Type":"application/json",...(s?{"X-Drive-Session":s}:{})}};const grant=async email=>{if(!email)return;try{await fetch(`${API}/drive/grant-folder-access`,{method:"POST",headers:headers(),credentials:"include",body:JSON.stringify({email})})}catch{}};const getEmail=b=>{let x=b;for(let i=0;i<6&&x;i++,x=x.parentElement){const m=x.innerText?.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);if(m)return m[0].toLowerCase()}return ""};document.addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;if(/^(Aprobar|Aceptar|Approve|Accept)/i.test(b.textContent.trim())){const email=getEmail(b);if(email)setTimeout(()=>grant(email),1800)}},true);patchLabel();new MutationObserver(patchLabel).observe(document.documentElement,{childList:true,subtree:true})})();
